import{_ as a,a0 as l,w as d,s as p,I as s,x as t,a1 as i,A as n,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"以单用户模式启动 CentOS/RHEL 7/8 的三种方法 | LCTT x X-CMD","titleTemplate":false,"description":"以单用户模式启动 CentOS/RHEL 7/8 的三种方法 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"以单用户模式启动 CentOS/RHEL 7/8 的三种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"以单用户模式启动 CentOS/RHEL 7/8 的三种方法 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200430 Three Methods Boot CentOS-RHEL 7-8 Systems in Single User Mode","title":"以单用户模式启动 CentOS/RHEL 7/8 的三种方法","tag":"202005","desc":""},"relativePath":"202005/20200430 Three Methods Boot CentOS-RHEL 7-8 Systems in Single User Mode.md","filePath":"[post].md"}'),g={name:"202005/20200430 Three Methods Boot CentOS-RHEL 7-8 Systems in Single User Mode.md"};function h(u,e,c,b,k,m){const o=l("Link");return d(),p("div",null,[e[27]||(e[27]=s("h1",{id:"以单用户模式启动-centos-rhel-7-8-的三种方法",tabindex:"-1"},[t("以单用户模式启动 CentOS/RHEL 7/8 的三种方法 "),s("a",{class:"header-anchor",href:"#以单用户模式启动-centos-rhel-7-8-的三种方法","aria-label":"Permalink to “以单用户模式启动 CentOS/RHEL 7/8 的三种方法”"},"​")],-1)),e[28]||(e[28]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/03/230109uw1f9zvv9upbhwv8.jpg",alt:""})],-1)),e[29]||(e[29]=s("p",null,"单用户模式，也被称为维护模式，超级用户可以在此模式下恢复/修复系统问题。",-1)),e[30]||(e[30]=s("p",null,"通常情况下，这类问题在多用户环境中修复不了。系统可以启动但功能不能正常运行或者你登录不了系统。",-1)),s("p",null,[e[1]||(e[1]=t("在基于 ",-1)),i(o,{href:"https://www.2daygeek.com/category/red-hat/"},{default:n(()=>[...e[0]||(e[0]=[t("Red Hat",-1)])]),_:1}),e[2]||(e[2]=t("（RHEL）7/8 的系统中，使用 ",-1)),e[3]||(e[3]=s("code",null,"runlevel1.target",-1)),e[4]||(e[4]=t(" 或 ",-1)),e[5]||(e[5]=s("code",null,"rescue.target",-1)),e[6]||(e[6]=t(" 来实现。",-1))]),e[31]||(e[31]=s("p",null,"在此模式下，系统会挂载所有的本地文件系统，但不开启网络接口。",-1)),e[32]||(e[32]=s("p",null,"系统仅启动特定的几个服务和修复系统必要的尽可能少的功能。",-1)),e[33]||(e[33]=s("p",null,"当你想运行文件系统一致性检查来修复损坏的文件系统，或忘记 root 密码后重置密码，或要修复系统上的一个挂载点问题时，这个方法会很有用。",-1)),s("p",null,[e[9]||(e[9]=t("你可以用下面三种方法以单用户模式启动 ",-1)),i(o,{href:"https://www.2daygeek.com/category/centos/"},{default:n(()=>[...e[7]||(e[7]=[t("CentOS",-1)])]),_:1}),e[10]||(e[10]=t("/",-1)),i(o,{href:"https://www.2daygeek.com/category/rhel/"},{default:n(()=>[...e[8]||(e[8]=[t("RHEL",-1)])]),_:1}),e[11]||(e[11]=t(" 7/8 系统。",-1))]),e[34]||(e[34]=r('<ul><li>方法 1：通过向内核添加 <code>rd.break</code> 参数来以单用户模式启动 CentOS/RHEL 7/8 系统</li><li>方法 2：通过用 <code>init=/bin/bash</code> 或 <code>init=/bin/sh</code> 替换内核中的 <code>rhgb quiet</code> 语句来以单用户模式启动 CentOS/RHEL 7/8 系统</li><li>方法 3：通过用 <code>rw init=/sysroot/bin/sh</code> 参数替换内核中的 <code>ro</code> 语句以单用户模式启动 CentOS/RHEL 7/8 系统</li></ul><h3 id="方法-1" tabindex="-1">方法 1 <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 1”">​</a></h3><p>通过向内核添加 <code>rd.break</code> 参数来以单用户模式启动 CentOS/RHEL 7/8 系统。</p><p>重启你的系统，在 GRUB2 启动界面，按下 <code>e</code> 键来编辑选中的内核。你需要选中第一行，第一个是最新的内核，然而如果你想用旧的内核启动系统你也可以选择其他的行。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-2.png" alt=""></p><p>根据你的 RHEL/CentOS 版本，找到 <code>linux16</code> 或 <code>linux</code> 语句，按下键盘上的 <code>End</code> 键，跳到行末，像下面截图中展示的那样添加关键词 <code>rd.break</code>，按下 <code>Ctrl+x</code> 或 <code>F10</code> 来进入单用户模式。</p><p>如果你的系统是 RHEL/CentOS 7，你需要找 <code>linux16</code>，如果你的系统是 RHEL/CentOS 8，那么你需要找 <code>linux</code>。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-3.png" alt=""></p><p>这个修改会让你的 root 文件系统以 “只读（<code>ro</code>）” 模式挂载。你可以用下面的命令来验证下。下面的输出也明确地告诉你当前是在 “<ruby>紧急模式<rt>Emergency Mode</rt></ruby>”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount | grep root</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-5.png" alt=""></p><p>为了修改 <code>sysroot</code> 文件系统，你需要用读写模式（<code>rw</code>）重新挂载它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -o remount,rw /sysroot</span></span></code></pre></div><p>运行下面的命令修改环境，这就是大家熟知的 “监禁目录” 或 “chroot 监狱”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chroot /sysroot</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-8.png" alt=""></p><p>现在，单用户模式已经完全准备好了。当你修复了你的问题要退出单用户模式时，执行下面的步骤。</p><p>CentOS/RHEL 7/8 默认使用 SELinux，因此创建下面的隐藏文件，这个文件会在下一次启动时重新标记所有文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># touch /.autorelabel</span></span></code></pre></div><p>最后，用下面的命令重启系统。你也可以输入两次 <code>exit</code> 命令来重启你的系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot -f</span></span></code></pre></div><h3 id="方法-2" tabindex="-1">方法 2 <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 2”">​</a></h3><p>通过用 <code>init=/bin/bash</code> 或 <code>init=/bin/sh</code> 替换内核中的 <code>rhgb quiet</code> 语句来以单用户模式启动 CentOS/RHEL 7/8 系统。</p><p>重启你的系统，在 GRUB2 启动界面，按下 <code>e</code> 键来编辑选中的内核。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-2.png" alt=""></p><p>找到语句 <code>rhgb quiet</code>，用 <code>init=/bin/bash</code> 或 <code>init=/bin/sh</code> 替换它，然后按下 <code>Ctrl+x</code> 或 <code>F10</code> 来进入单用户模式。</p><p><code>init=/bin/bash</code> 的截图。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/method-reset-forgotten-root-password-on-rhel-7-centos-7-1.png" alt=""></p><p><code>init=/bin/sh</code> 的截图。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/method-reset-forgotten-root-password-on-rhel-7-centos-7-1a.png" alt=""></p><p>默认情况下，上面的操作会以只读（<code>ro</code>）模式挂载你的 <code>/</code> 分区，因此你需要以读写（<code>rw</code>）模式重新挂载 <code>/</code> 文件系统，这样才能修改它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -o remount,rw /</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/method-reset-forgotten-root-password-on-rhel-7-centos-7-4.png" alt=""></p><p>现在你可以执行你的任务了。当结束时，执行下面的命令来开启重启时的 SELinux 重新标记。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># touch /.autorelabel</span></span></code></pre></div><p>最后，重启系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># exec /sbin/init 6</span></span></code></pre></div><h3 id="方法-3" tabindex="-1">方法 3 <a class="header-anchor" href="#方法-3" aria-label="Permalink to “方法 3”">​</a></h3><p>通过用 <code>rw init=/sysroot/bin/sh</code> 参数替换内核中的 <code>ro</code> 单词，以单用户模式启动 CentOS/RHEL 7/8 系统。</p><p>为了中断自动启动的过程，重启你的系统并在 GRUB2 启动界面按下任意键。</p><p>现在会展示你系统上所有可用的内核，选择最新的内核，按下 <code>e</code> 键来编辑选中的内核参数。</p><p>找到以 <code>linux</code> 或 <code>linux16</code> 开头的语句，用 <code>rw init=/sysroot/bin/sh</code> 替换 <code>ro</code>。替换完后按下 <code>Ctrl+x</code> 或 <code>F10</code> 来进入单用户模式。</p><p>运行下面的命令把环境切换为 “chroot 监狱”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chroot /sysroot</span></span></code></pre></div><p>如果需要，做出必要的修改。修改完后，执行下面的命令来开启重启时的 SELinux 重新标记。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># touch /.autorelabel</span></span></code></pre></div><p>最后，重启系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot -f</span></span></code></pre></div><hr>',49)),s("p",null,[e[13]||(e[13]=t("via: ",-1)),i(o,{href:"https://www.2daygeek.com/boot-centos-7-8-rhel-7-8-single-user-mode/"},{default:n(()=>[...e[12]||(e[12]=[t("https://www.2daygeek.com/boot-centos-7-8-rhel-7-8-single-user-mode/",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=t("作者：",-1)),i(o,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...e[14]||(e[14]=[t("Magesh Maruthamuthu",-1)])]),_:1}),e[19]||(e[19]=t(" 选题：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[15]||(e[15]=[t("lujun9972",-1)])]),_:1}),e[20]||(e[20]=t(" 译者：",-1)),i(o,{href:"https://github.com/lxbwolf"},{default:n(()=>[...e[16]||(e[16]=[t("lxbwolf",-1)])]),_:1}),e[21]||(e[21]=t(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[24]||(e[24]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[22]||(e[22]=[t("LCTT",-1)])]),_:1}),e[25]||(e[25]=t(" 原创编译，",-1)),i(o,{href:"https://linux.cn/"},{default:n(()=>[...e[23]||(e[23]=[t("Linux中国",-1)])]),_:1}),e[26]||(e[26]=t(" 荣誉推出",-1))])])}const C=a(g,[["render",h]]);export{y as __pageData,C as default};
